import { analysisSource, basePlan, calculate, calculationText, displayCell, fieldLabel, filterValues, formatValue, groupValues, includedRows, planFilters, valuesFor } from '../app/src/core/engine';
import { budgetExceptions, comparePeriods, describePlanChanges, sourceQuality, analysisExceptions } from '../app/src/core/analysis';
import { validatePlan, demoPlan } from '../app/src/core/planner';
import { compileExpression } from '../app/src/core/expression';
import { parseFile } from '../app/src/core/import';
import { contextualCsv, executiveReportHtml } from '../app/src/core/executive-export';
import { sapSource } from '../app/src/server/seed';
import type { Source, Plan, ImportSample, Metric } from '../app/src/core/types';

type Note = { text:string; at:string };
type Board = { id:string; sourceId:string; plan:Plan; notes:Note[]; favorite:boolean; at:string; revisions:{ plan:Plan; at:string }[] };
type State = { version:2; sources:Source[]; boards:Board[]; work:{ sourceId:string; plan:Plan; notes:Note[]; boardId?:string; prompt?:string; noteDraft?:string }; events:{ text:string; at:string }[]; summary:string };
type Screen = 'home'|'explore'|'boards'|'sources'|'present';
declare global { interface Window { CLARA_ICONS:Record<string,string>; CLARA_PROTOTYPE:{ navigate:(screen:Screen)=>void; state:()=>State } } }
const E = (value:unknown) => String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const I = (name:string) => window.CLARA_ICONS[name] || '';
const $ = <T extends HTMLElement=HTMLElement>(selector:string) => document.querySelector<T>(selector)!;
const clone = <T>(value:T):T => structuredClone(value);
const focusSelector = (element:HTMLElement|null) => element?.id?'#'+CSS.escape(element.id):element?.dataset.action?'button'+['action','id','key','value','screen','index'].filter(key=>element.dataset[key]!=null).map(key=>`[data-${key}="${CSS.escape(element.dataset[key]!)}"]`).join(''):element?.matches('button[type="submit"]')&&element.closest('form')?.id?'#'+CSS.escape(element.closest('form')!.id)+' button[type="submit"]':'';
const B = (label:string, action:string, cls='secondary', icon='', extra='') => `<button type="button" class="${cls}" data-action="${action}" ${extra}>${icon?I(icon):''}${label}</button>`;
const when = (at:string) => new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(at));
const colors = ['#2455dc','#101e39','#137c85','#e79568','#658cc1','#a2b63d'];
const storageKey='clara:design:workbench:v2';
const blankPlan=(source:Source):Plan=>({...basePlan(source),message:'Confira o recorte, a fonte e o cálculo antes de salvar.'});
function initial():State {
  const finance=sapSource('finance','prototype'),sales=sapSource('sales','prototype'),inventory=sapSource('inventory','prototype');
  const plan=blankPlan(finance); plan.title='Despesas e orçamento';
  const at=new Date().toISOString();
  return {version:2,sources:[finance,sales,inventory],boards:[
    {id:crypto.randomUUID(),sourceId:finance.id,plan:clone(plan),notes:[],favorite:true,at,revisions:[]},
    {id:crypto.randomUUID(),sourceId:finance.id,plan:{...clone(plan),title:'Tecnologia · além do orçamento',filters:{group:'Tecnologia'}},notes:[],favorite:false,at,revisions:[]},
    {id:crypto.randomUUID(),sourceId:sales.id,plan:{...blankPlan(sales),title:'Vendas por região'},notes:[],favorite:false,at,revisions:[]},
  ],work:{sourceId:finance.id,plan,notes:[]},events:[],summary:''};
}
function readState():State {
  try {
    const raw=localStorage.getItem(storageKey);if(!raw)return initial();const value=JSON.parse(raw) as State;
    if(value.version!==2||!Array.isArray(value.sources)||!value.sources.length||!Array.isArray(value.boards))return initial();
    for(const source of value.sources){if(!Array.isArray(source.rows)||source.rows.length>20000||!Array.isArray(source.columns))throw new Error('Fonte inválida');validatePlan(blankPlan(source),source);}
    const source=value.sources.find(item=>item.id===value.work.sourceId);if(!source)throw new Error('Fonte removida');validatePlan(value.work.plan,source);
    value.boards=value.boards.filter(board=>{try{const source=value.sources.find(item=>item.id===board.sourceId);return source&&validatePlan(board.plan,source);}catch{return false;}});
    value.events=(value.events||[]).slice(0,30);value.summary=value.summary||'';return value;
  } catch{return initial();}
}
let state=readState(),screen:Screen='home',boardSearch='',favoriteOnly=false,chartMode='bar',sortAscending=false,recordPage=0,recordQuery='',recordSource='',slide=0,pendingImport:ImportSample|null=null,lastMessage='',dialogOpener='',toastTimer:ReturnType<typeof setTimeout>;
const source=()=>state.sources.find(item=>item.id===state.work.sourceId)!;
const plan=()=>state.work.plan;
const resolved=()=>analysisSource(source(),plan());
const metric=()=>resolved().metrics.find(item=>item.key===plan().primaryMetric)!;
const rows=()=>includedRows(source(),planFilters(plan()));
const fv=(value:number|null, item:Metric=metric(), compact=false)=>formatValue(value,item,compact);
const grouped=()=>groupValues(source(),plan()).sort((a,b)=>sortAscending?(a.value??Infinity)-(b.value??Infinity):(b.value??-Infinity)-(a.value??-Infinity));
function notify(text:string,error=false){const node=$('#toast');node.innerHTML=I(error?'CircleAlert':'CircleCheck')+`<span>${E(text)}</span>`;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,5000);}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));$('#storage-status').textContent='Ajustes salvos neste navegador · IA demonstrativa';return true;}catch{$('#storage-status').textContent='Sem espaço no navegador · ajustes somente em memória';notify('Armazenamento indisponível. Exporte sua análise para preservar os ajustes.',true);return false;}}
function event(text:string){state.events.unshift({text,at:new Date().toISOString()});state.events=state.events.slice(0,30);persist();}
function download(content:string,title:string,extension:string,type:string){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=`${title.replace(/[^\p{L}\p{N} -]/gu,'')||'CLARA'}.${extension}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function options(items:{value:string;label:string}[],chosen:string){return items.map(item=>`<option value="${E(item.value)}" ${chosen===item.value?'selected':''}>${E(item.label)}</option>`).join('');}
function selectField(label:string,id:string,items:{value:string;label:string}[],chosen:string,extra=''){return `<label class="field" for="${id}">${E(label)}<select id="${id}" ${extra}>${options(items,chosen)}</select></label>`;}
function apply(next:Plan,text:string){state.work.plan=validatePlan(next,source());state.summary='';event(text);render(true);}
function navigate(next:Screen){screen=next;window.history.pushState(null,'','#'+next);render();$('#main').focus({preventScroll:true});window.scrollTo(0,0);}
const routeNames:Record<Screen,string>={home:'Painel',explore:'Explorar dados',boards:'Minhas análises',sources:'Fontes de dados',present:'Apresentar'};
const navIcons:Record<Screen,string>={home:'LayoutDashboard',explore:'ChartNoAxesCombined',boards:'FolderOpen',sources:'Database',present:'Presentation'};
function navMarkup(){return (Object.keys(routeNames) as Screen[]).map(key=>B(`<span>${routeNames[key]}</span>${key==='boards'?`<span class="nav-counter">${state.boards.length}</span>`:''}`,'nav','',navIcons[key],`data-screen="${key}" aria-label="${routeNames[key]}" ${screen===key?'aria-current="page"':''}`)).join('');}
function render(keepFocus=true){const active=document.activeElement as HTMLElement|null;const selector=keepFocus?focusSelector(active):'';
  $('#rail').innerHTML=`<div class="brand"><span class="brand-mark">${I('Asterisk')}</span><span class="brand-text">CLARA<span class="point">.</span></span></div><p class="rail-caption">Um novo olhar para seus dados.</p>${B(`<span>Meu espaço de análise</span>${I('ChevronDown')}`,'workspace','workspace-button')}<div class="nav-label">Espaço de trabalho</div><nav>${navMarkup()}</nav><div class="rail-bottom"><div class="rail-tip">${I('Sparkles')}<h3 style="font-size:13px;margin-top:8px">Uma pergunta abre caminhos.</h3><p>Monte um recorte, teste uma hipótese e confira o que os dados dizem.</p>${B('Começar uma análise','new','', 'ArrowRight')}</div><div class="profile"><span class="avatar">M</span><div><strong style="font-size:12px">Marina Costa</strong><br><small>Espaço local de demonstração</small></div></div></div>`;
  $('#topbar').innerHTML=`${B('','menu','mobile-menu icon-button','Menu','aria-label="Abrir navegação"')}<div class="breadcrumb"><span>Meu espaço</span>${I('ChevronRight')}<strong>${routeNames[screen]}</strong></div>${B(`<span>${I('Search')}<span class="command-text">Buscar uma análise ou ação</span></span><kbd>Ctrl K</kbd>`,'command','command-trigger','','aria-label="Buscar uma análise ou ação"')}${B('','activity','icon-button','Bell','aria-label="Ver atividade local"')}`;
  $('#main').innerHTML=`<div class="view-enter">${screen==='home'?home():screen==='explore'?explore():screen==='boards'?boards():screen==='sources'?sources():presentation()}</div>`;
  if(selector){const target=document.querySelector<HTMLElement>(selector);(target||$('#main')).focus({preventScroll:true});}
}
function stats(work=false){const primary=metric(),actual=calculate(primary,rows()),secondary=resolved().metrics.find(item=>item.key===plan().secondaryMetric),budget=secondary?calculate(secondary,rows()):null;const difference=actual!=null&&budget!=null?actual-budget:null;const dates=source().dateColumn?filterValues(source(),source().dateColumn!).filter(value=>value.length===7):[];
  const compare=dates.length>1?comparePeriods(source(),{...plan(),periodComparison:{dateColumn:source().dateColumn!,current:dates.at(-1)!,previous:dates.at(-2)!}})[0]:null;
  const parts=[`<article class="stat"><div class="stat-label"><span>${E(primary.label)}</span>${I('ChartNoAxesCombined')}</div><strong data-testid="actual">${fv(actual)}</strong><p>${rows().length} registros considerados</p></article>`,
  `<article class="stat"><div class="stat-label"><span>${secondary?E(secondary.label):'Grupos no recorte'}</span>${I('Layers')}</div><strong>${secondary?fv(budget,secondary):grouped().length}</strong><p>${secondary?'Mesma fonte, mesmos critérios.':E(fieldLabel(source(),plan().groupBy))}</p></article>`,
  `<article class="stat"><div class="stat-label"><span>${difference!=null?(difference>0?'Acima do orçamento':'Saldo do orçamento'):'Registros da fonte'}</span>${I(difference!=null&&difference>0?'CircleAlert':'CircleCheck')}</div><strong>${difference!=null?fv(Math.abs(difference)):source().rows.length}</strong><p class="${difference!=null&&difference>0?'warning':'positive'}">${difference!=null&&budget?`${(Math.abs(difference)/Math.abs(budget)*100).toLocaleString('pt-BR',{maximumFractionDigits:1})}% ${difference>0?'acima':'abaixo'} do orçamento`:'Fonte disponível para conferir'}</p></article>`];
  if(!work)parts.push(`<article class="stat"><div class="stat-label"><span>${compare?'Último mês vs. anterior':'Indicadores disponíveis'}</span>${I('ChartLine')}</div><strong>${compare?.percentage!=null?(compare.percentage>0?'+':'')+compare.percentage.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':resolved().metrics.length}</strong><p>${compare?`${E(displayCell(source(),source().dateColumn!,dates.at(-1)!))} · mesma seleção de grupos`:'Inclua fórmulas no explorador'}</p></article>`);
  return `<div class="${work?'work-stats':'stats'}">${parts.join('')}</div>`;
}
function trendSvg(s:Source,p:Plan,mini=false){if(!p.dateColumn)return `<p class="muted small">Esta fonte não possui datas para uma evolução temporal.</p>`;const data=groupValues(s,p,p.dateColumn),primary=analysisSource(s,p).metrics.find(item=>item.key===p.primaryMetric)!;if(!data.length)return '<p class="muted small">Nenhum período nesse recorte.</p>';
  const width=600,height=mini?62:220,left=mini?0:56,right=mini?0:15,top=mini?7:18,bottom=mini?4:34;const values=data.flatMap(row=>[row.value,row.comparison]).filter((item):item is number=>item!=null);const min=Math.min(0,...values),max=Math.max(1,...values),range=max-min||1;const x=(i:number)=>data.length===1?(left+width-right)/2:left+i*(width-left-right)/(data.length-1);const y=(v:number)=>top+(max-v)/range*(height-top-bottom);const path=(key:'value'|'comparison')=>data.filter(row=>row[key]!=null).map((row,index)=>`${index===0?'M':'L'}${x(data.indexOf(row))},${y(row[key]!)}`).join(' ');const primaryPath=path('value');const comparisonPath=path('comparison');
  return `<svg class="chart-svg" viewBox="0 0 ${width} ${height}" ${mini?'aria-hidden="true"':`role="img" aria-label="${E(primary.label)} por mês. Valores exatos disponíveis em Ver valores temporais."`}>${mini?'':[0,.5,1].map(i=>`<line x1="${left}" x2="${width-right}" y1="${top+i*(height-top-bottom)}" y2="${top+i*(height-top-bottom)}" stroke="#e0e6ef"/><text x="0" y="${top+i*(height-top-bottom)+4}">${E(formatValue(max-i*range,primary,true))}</text>`).join('')}<path d="${primaryPath}" fill="none" stroke="#2455dc" stroke-width="${mini?3:2.6}"/>${comparisonPath?`<path d="${comparisonPath}" fill="none" stroke="#137c85" stroke-width="2" stroke-dasharray="5 4"/>`:''}${mini?'':data.map((row,i)=>`<circle cx="${x(i)}" cy="${y(row.value??0)}" r="4" fill="#2455dc"><title>${E(displayCell(s,p.dateColumn!,row.name))}: ${E(formatValue(row.value,primary))}</title></circle><text x="${x(i)}" y="${height-8}" text-anchor="middle">${E((/^\d{4}-\d{2}/.test(row.name)?new Intl.DateTimeFormat('pt-BR',{month:'short',year:'2-digit',timeZone:'UTC'}).format(new Date(row.name.slice(0,7)+'-01T00:00:00Z')):row.name))}</text>`).join('')}</svg>`;
}
function insight(){const exceptions=budgetExceptions(source(),plan()).filter(item=>item.key===plan().groupBy),top=exceptions[0],leader=grouped()[0];return `<section class="panel insight-panel"><div class="insight-label">${I('Sparkles')} FORA DA CURVA</div><h3>${top?`${E(displayCell(source(),top.key,top.value))} está acima do previsto.`:leader?`${E(leader.name)} lidera o recorte.`:'Seu recorte está vazio.'}</h3><div class="insight-amount">${top?fv(top.difference):leader?fv(leader.value):'—'}</div><p>${top?'de diferença entre realizado e orçamento. Esse desvio merece um olhar próprio.':leader?`${leader.count} registros compõem este grupo. Abra o recorte para conferir sua composição.`:'Restaure os filtros ou selecione outro grupo para continuar.'}</p><div class="insight-divider"></div><p>Leitura por regras de cálculo, com origem conferível. Nenhum modelo de IA foi acionado.</p>${leader?B('Investigar esse grupo','drill','dark-button','ArrowUpRight',`data-key="${E(top?.key||plan().groupBy)}" data-value="${E(top?.value||leader.name)}"`):B('Restaurar recorte','reset','dark-button','Undo2')}</section>`;}
function home(){const actual=calculate(metric(),rows()),secondary=resolved().metrics.find(item=>item.key===plan().secondaryMetric),budget=secondary?calculate(secondary,rows()):null,percentage=budget&&actual!=null?actual/budget*100:0;
  return `<div class="page-head"><div><span class="overline">Seu negócio, em perspectiva</span><h1>Bom dia, Marina.</h1><p>Retome uma pergunta. Encontre um desvio. Construa a próxima decisão.</p></div><div class="actions">${B('Importar dados','import','secondary','Upload')}${B('Nova análise','new','primary','Plus')}</div></div><div class="hero-grid"><section class="hero"><div class="hero-copy"><span class="overline">CLARA · seu estúdio de análises</span><h2>Enxergue além<br>do total.</h2><p>O recorte atual tem ${rows().length} registros. Cada número pode abrir uma nova investigação.</p>${B('Continuar minha análise','nav','lime-button','ArrowUpRight','data-screen="explore"')}</div><div class="hero-art"><div class="orb" style="--angle:${Math.max(0,Math.min(percentage,100))*3.6}deg"><div class="orb-text"><strong>${budget?percentage.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':rows().length}</strong><small>${budget?'do orçamento':'registros no recorte'}</small></div></div><div class="hero-sticker">${I('Layers')}${E(source().name)}</div></div></section><section class="start-card"><div><span class="tag">${I('MessageSquare')} Uma nova perspectiva</span><h3>Qual é sua próxima pergunta?</h3><p>Escolha uma hipótese ou monte uma análise com seus próprios dados.</p></div><div>${B(`<span>Ex.: o que mudou neste mês?</span>${I('ArrowUpRight')}`,'new','question-launch')}<div class="quick-actions">${B('Comparar meses','quick-compare','', 'ChartLine')}${B('Testar uma fórmula','formula','', 'Calculator')}${B('Conferir dados','records','', 'Table')}</div></div></section></div>${stats()}<div class="home-charts"><section class="panel"><div class="chart-heading"><div><h3>A história por trás dos números</h3><p>${E(source().name)} · evolução no recorte atual</p></div>${B('Explorar','nav','text-button small','ArrowUpRight','data-screen="explore"')}</div><div class="chart-legend"><span><i class="legend-dot"></i>${E(metric().label)}</span>${secondary?`<span><i class="legend-dot" style="background:var(--teal)"></i>${E(secondary.label)}</span>`:''}</div>${trendSvg(source(),plan())}<div class="chart-note"><span>Datas e valores da fonte · sem projeções</span>${B('Ver valores temporais','trend-values','text-button small','Table')}</div></section>${insight()}</div><div class="section-heading"><div><h2>Suas análises, sempre por perto</h2><p>Perguntas salvas com fonte, recorte e cálculo.</p></div>${B('Ver todas','nav','text-button small','ArrowRight','data-screen="boards"')}</div><div class="board-grid">${state.boards.slice(0,3).map(boardCard).join('')}</div>`;
}
function boardCard(board:Board){const s=state.sources.find(item=>item.id===board.sourceId)!;return `<article class="board" data-board="${board.id}"><div class="board-top"><span class="tag">${E(s.domain)}</span>${B('','favorite','star','Star',`data-id="${board.id}" aria-pressed="${board.favorite}" aria-label="${board.favorite?'Remover favorito':'Favoritar'} ${E(board.plan.title)}"`)}</div><h3>${B(E(board.plan.title),'open-board','board-title','',`data-id="${board.id}"`)}</h3><p>${E(s.name)} · ${Object.keys(planFilters(board.plan)).length?'recorte personalizado':'todos os registros'}</p><div class="board-mini">${trendSvg(s,board.plan,true)}</div><div class="board-bottom"><span>Versão ${board.revisions.length+1} · ${E(when(board.at))}</span>${B('Abrir','open-board','','ArrowUpRight',`data-id="${board.id}"`)}</div></article>`;}
function boards(){const list=state.boards.filter(board=>(!favoriteOnly||board.favorite)&&board.plan.title.toLocaleLowerCase('pt-BR').includes(boardSearch.toLocaleLowerCase('pt-BR')));return `<div class="page-head"><div><span class="overline">Sua memória de trabalho</span><h1>Análises que você construiu.</h1><p>Abra, refine, duplique e prepare seus resultados para compartilhar.</p></div>${B('Nova análise','new','primary','Plus')}</div><div class="section-heading"><div class="actions"><div class="segmented">${B('Todas','all-boards','','',`aria-pressed="${!favoriteOnly}"`)}${B('Favoritas','favorite-boards','','Star',`aria-pressed="${favoriteOnly}"`)}</div><span class="muted small">${state.boards.length} análises neste navegador</span></div><input id="board-search" class="search-input" aria-label="Buscar análise salva" placeholder="Buscar uma análise…" value="${E(boardSearch)}"></div><div id="board-results" class="board-grid">${list.map(boardCard).join('')||'<div class="empty"><h3>Nenhuma análise encontrada</h3><p>Tente outro nome ou remova o filtro de favoritos.</p></div>'}</div>`;}
function chips(){return Object.entries(planFilters(plan())).map(([key,value])=>B(`${E(fieldLabel(source(),key))}: ${E((Array.isArray(value)?value:[value]).map(v=>displayCell(source(),key,v)).join(' ou '))}${I('X')}`,'clear-filter','','',`data-key="${E(key)}" aria-label="Remover filtro ${E(fieldLabel(source(),key))}"`)).join('');}
function groupBars(){const data=grouped().slice(0,10),max=Math.max(1,...data.flatMap(row=>[Math.abs(row.value??0),Math.abs(row.comparison??0)]));return `<div class="group-bars">${data.map((row,index)=>`<button type="button" class="group-bar" data-action="drill" data-key="${E(plan().groupBy)}" data-value="${E(row.name)}" aria-label="Investigar ${E(row.name)}"><div class="bar-label"><span>${E(row.name)}<small> · ${row.count} registros</small></span><strong>${fv(row.value)}</strong></div><div class="bar-track"><div class="bar-fill" style="--width:${Math.abs(row.value??0)/max*100}%;--color:${colors[index%colors.length]}"></div></div>${row.comparison!=null?`<div class="bar-budget" style="--width:${Math.abs(row.comparison)/max*100}%"><i></i></div>`:''}</button>`).join('')}</div>${data.some(row=>(row.value??0)<0)?'<p class="tiny-note">Comprimentos mostram magnitudes; sinais estão nos valores.</p>':''}`;}
function valueTable(temporal=false){const data=temporal&&plan().dateColumn?groupValues(source(),plan(),plan().dateColumn!):grouped();return `<div class="table-scroll"><table class="data-table"><caption>${temporal?'Períodos e valores exatos':'Valores exatos por '+E(fieldLabel(source(),plan().groupBy))}</caption><thead><tr><th scope="col">${temporal?'Período':E(fieldLabel(source(),plan().groupBy))}</th><th scope="col">${E(metric().label)}</th>${plan().secondaryMetric?'<th scope="col">Orçamento</th>':''}<th scope="col">Registros</th></tr></thead><tbody>${data.slice(0,100).map(row=>`<tr><th scope="row">${temporal?E(displayCell(source(),plan().dateColumn!,row.name)):B(E(row.name),'drill','text-button','',`data-key="${E(plan().groupBy)}" data-value="${E(row.name)}"`)}</th><td>${fv(row.value)}</td>${plan().secondaryMetric?`<td>${fv(row.comparison)}</td>`:''}<td>${row.count}</td></tr>`).join('')}</tbody></table></div>${data.length>100?'<p class="tiny-note">100 primeiros grupos. A exportação inclui todos.</p>':''}`;}
function compareMarkup(){const items=comparePeriods(source(),plan());if(!items.length)return '';const item=items[0];return `<section class="comparison"><h3>${E(displayCell(source(),plan().periodComparison!.dateColumn,plan().periodComparison!.current))} vs. ${E(displayCell(source(),plan().periodComparison!.dateColumn,plan().periodComparison!.previous))}</h3><div class="comparison-grid"><div><small>Período atual</small><strong>${fv(item.currentValue,item.metric)}</strong></div><div><small>Referência</small><strong>${fv(item.previousValue,item.metric)}</strong></div><div><small>Variação</small><strong>${item.percentage==null?'Não calculável':(item.percentage>0?'+':'')+item.percentage.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%'}</strong></div></div>${B('Ajustar comparação','compare','text-button')}${B('Remover','remove-compare','text-button','','style="margin-left:14px"')}<p class="tiny-note">Mantém os filtros de grupos e critérios; substitui somente o período em cada cálculo.</p></section>`;}
function explore(){const s=source(),p=plan(),dates=s.dateColumn?filterValues(s,s.dateColumn).filter(v=>v.length===7):[],sourceOptions=state.sources.map(item=>({value:item.id,label:item.name})),metrics=resolved().metrics;const changes=state.work.boardId?describePlanChanges(state.boards.find(board=>board.id===state.work.boardId)!.plan,p,s):[];const leader=grouped()[0];
  return `<div class="page-head"><div><span class="overline">Explore · investigue · confira</span><h1>${E(p.title)}</h1><p>${changes.length?'Ajustes em andamento · '+E(changes[0]):'Clique em um grupo para investigar. Seus ajustes ficam preservados.'}</p></div><div class="actions">${state.work.boardId?B('','history','secondary icon-button','History','aria-label="Histórico da análise"'):''}${B('Configurar','configure','secondary','SlidersHorizontal')}${B('Salvar análise','save','primary','Save')}</div></div><div class="work-layout"><div><div class="work-toolbar">${selectField('Fonte','active-source',sourceOptions,s.id)}${s.dateColumn?selectField('Período','period-filter',[{value:'__all__',label:'Todos os meses'},...dates.map(value=>({value,label:displayCell(s,s.dateColumn!,value)}))],p.filters[s.dateColumn]||'__all__'):''}${selectField('Agrupar por','group-by',s.columns.filter(column=>column.type!=='number').map(column=>({value:column.key,label:column.label})),p.groupBy)}<div class="toolbar-end">${B('Seleções','multi','secondary small','Filter')}${B('Comparar','compare','secondary small','ChartLine',!s.dateColumn?'disabled':'')}</div></div><div class="filter-chips">${Object.keys(planFilters(p)).length?`<span>Recorte em edição</span>${chips()}${B('Limpar recorte','reset','text-button small','Undo2')}`:'Todos os registros que atendem aos critérios da fonte.'}</div>${stats(true)}${compareMarkup()}<section class="panel work-chart"><div class="chart-heading"><div><h3>${E(metric().label)} por ${E(fieldLabel(s,p.groupBy).toLowerCase())}</h3><p>Clique para abrir o recorte; filtros e cálculos acompanham sua investigação.</p></div><div class="segmented">${B('','chart-bar','','ChartBar',`aria-label="Mostrar barras" aria-pressed="${chartMode==='bar'}"`)}${B('','chart-line','','ChartLine',`aria-label="Mostrar evolução" aria-pressed="${chartMode==='line'}" ${!p.dateColumn?'disabled':''}`)}</div></div>${chartMode==='line'?trendSvg(s,p):groupBars()}<div class="chart-note"><span>${plan().secondaryMetric?'Barra fina: orçamento · mesma unidade.':grouped().length+' grupos · o total inclui todos.'}</span>${B('Ver registros','records','text-button small','Table')}</div></section>${p.selectedMetrics?.length?`<div class="extra-metrics">${metrics.filter(item=>p.selectedMetrics?.includes(item.key)&&item.key!==p.primaryMetric).map(item=>`<article class="stat"><div class="stat-label">${E(item.label)}</div><strong>${fv(calculate(item,rows()),item)}</strong><p>${E(item.expression||calculationText(item,s))}</p></article>`).join('')}</div>`:''}<section class="panel work-details"><div class="table-heading"><h3>De perto, os valores.</h3>${B(sortAscending?'Maior primeiro':'Menor primeiro','sort','text-button','SlidersHorizontal')}</div>${valueTable()}<div class="calc-path">${I('Database')}<strong>${E(s.name)}</strong>${I('ChevronRight')}<span>${s.rule?E(fieldLabel(s,s.rule.column))+' = '+E(s.rule.value):'Todos os registros'}</span>${I('ChevronRight')}<span>${rows().length} registros no recorte</span>${I('ChevronRight')}${B('Conferir cálculo','calculation','text-button')}</div></section></div><aside class="work-aside"><section class="side-panel"><div class="assistant-title"><span class="assistant-mark">${I('Sparkles')}</span><div><h3>Um olhar da CLARA</h3><small>Assistente demonstrativo</small></div></div><div class="assistant-message">${E(lastMessage||`${leader?leader.name+' compõe '+fv(leader.value)+' neste recorte.':'Nenhum grupo neste recorte.'} Você pode investigar o grupo ou comparar dois períodos.`)}</div><div class="assistant-buttons">${leader?B('Investigar '+E(leader.name),'drill','','ArrowUpRight',`data-key="${E(p.groupBy)}" data-value="${E(leader.name)}"`):''}${B('Conferir a origem','calculation','','Database')}${B('Criar indicador','formula','','Calculator')}</div><form id="prompt-form" style="margin-top:16px"><label class="field" for="prompt">Refinar com uma pergunta<textarea id="prompt" placeholder="Ex.: despesas por categoria" maxlength="4000" required>${E(state.work.prompt)}</textarea></label><button type="submit" class="primary">Aplicar regras de demonstração ${I('ArrowRight')}</button></form><p class="tiny-note">Sem IA real: interpreta campos e filtros conhecidos. Perguntas sem dados geram esclarecimento.</p></section><section class="side-panel"><div class="assistant-title">${I('NotebookPen')}<h3>Suas observações</h3></div><form id="note-form"><label class="field" for="note">O que vale levar à reunião?<textarea id="note" placeholder="Registre uma hipótese ou conclusão…" maxlength="1000" required>${E(state.work.noteDraft)}</textarea></label><button type="submit" class="primary">Adicionar observação</button></form>${state.work.notes.map(note=>`<div class="note-card">${E(note.text)}<small>${E(when(note.at))}</small></div>`).join('')}<p class="tiny-note">Observações acompanham a análise salva neste navegador.</p></section><section class="side-panel"><h3 style="margin-bottom:12px">Pronta para a conversa?</h3><p class="muted small">Transforme o recorte atual em uma apresentação conferível.</p>${B('Preparar apresentação','nav','primary','Presentation','data-screen="present"')}</section></aside></div>`;
}
function sources(){return `<div class="page-head"><div><span class="overline">Tudo começa com uma boa fonte</span><h1>Dados com contexto.</h1><p>Confira estrutura, qualidade e registros antes de decidir o que analisar.</p></div>${B('Importar arquivo','import','primary','Upload')}</div><div class="local-notice"><strong>Arquivos locais de verdade.</strong> CSV, Excel com uma aba e JSON são processados neste navegador. Os exemplos SAP são simulados; este estudo não acessa o servidor da CLARA.</div><div class="source-grid">${state.sources.map(s=>{const q=sourceQuality(s),missing=q.reduce((sum,col)=>sum+col.missing,0),dates=s.dateColumn?valuesFor(s,s.dateColumn):[];return `<article class="source-card"><div class="source-icon">${I(s.origin==='file'?'FileSpreadsheet':'Database')}</div><h3>${E(s.name)}</h3><p>${s.origin==='sap-demo'?'SAP demonstrativo · dados ilustrativos':'Arquivo importado · processado localmente'}</p><dl><div><dt>Registros</dt><dd>${s.rows.length.toLocaleString('pt-BR')}</dd></div><div><dt>Colunas</dt><dd>${s.columns.length}</dd></div><div><dt>Células ausentes</dt><dd>${missing}</dd></div></dl><span class="tag ${missing?'orange':'green'}">${I(missing?'CircleAlert':'CircleCheck')}${missing?'Há dados para conferir':'Sem campos vazios'}</span><p style="margin-top:10px">${dates.length?E(displayCell(s,s.dateColumn!,dates[0]))+' a '+E(displayCell(s,s.dateColumn!,dates.at(-1)!)):'Sem coluna de datas configurada.'}</p><div class="actions">${B('Explorar','source-open','primary','ArrowUpRight',`data-id="${s.id}"`)}${B('Qualidade','quality','secondary','Eye',`data-id="${s.id}"`)}${B('Registros','records','text-button','Table',`data-id="${s.id}"`)}</div></article>`;}).join('')}<section class="source-card upload-card"><div class="source-icon">${I('Upload')}</div><h3>Traga uma nova perspectiva.</h3><p>Importe até 8 MB e 20 mil registros. Confira indicador e agrupamento antes de adicionar.</p>${B('Escolher arquivo','import','primary','Plus')}<p class="tiny-note">CSV · XLSX · JSON</p></section></div>`;}
function presentation(){const primary=metric(),actual=calculate(primary,rows()),exceptions=budgetExceptions(source(),plan()),top=exceptions[0],titles=['A pergunta e o resultado','Composição do recorte','O que pede atenção','Critérios e origem'];const body=slide===0?`<span class="overline">Sua pergunta, uma perspectiva.</span><h2>${E(plan().title)}</h2><div class="slide-number">${fv(actual)}</div><p>${E(state.summary||`${primary.label} no recorte atual. ${rows().length} registros da fonte ${source().name} considerados.`)}</p>`:slide===1?`<span class="overline">Composição do resultado</span><h2>Os grupos por trás do total.</h2>${groupBars()}`:slide===2?`<span class="overline">Da leitura à investigação</span><h2>${top?E(displayCell(source(),top.key,top.value))+' merece atenção.':'O maior grupo do recorte.'}</h2><div class="slide-number">${top?fv(top.difference):fv(grouped()[0]?.value??null)}</div><p>${top?'Diferença acima do orçamento neste recorte. Dimensões são analisadas separadamente.':E(grouped()[0]?.name||'Nenhum grupo disponível')}</p>${state.work.notes.length?`<p style="margin-top:20px">${E(state.work.notes.at(-1)!.text)}</p>`:''}`:`<span class="overline">Confiança para compartilhar</span><h2>Um resultado que pode ser conferido.</h2><p>Fonte: ${E(source().name)} · revisão ${source().revision}.</p><p style="margin-top:16px">${E(calculationText(primary,source()))}</p><p style="margin-top:16px">${source().rule?E(fieldLabel(source(),source().rule!.column))+' = '+E(source().rule!.value):'Todos os registros da fonte.'}</p><p style="margin-top:16px">${rows().length} registros no recorte · ${Object.entries(planFilters(plan())).map(([key,val])=>E(fieldLabel(source(),key))+': '+E(Array.isArray(val)?val.join(' ou '):val)).join('; ')||'Sem filtros adicionais.'}</p>`;
 return `<div class="page-head"><div><span class="overline">Do dado à conversa</span><h1>Leve uma história, com os números.</h1><p>Revise o recorte, acrescente sua leitura e prepare a reunião.</p></div><div class="actions">${B('CSV com contexto','export-csv','secondary','Table')}${B('Relatório','export-report','secondary','Download')}${B('Baixar apresentação','export-slides','primary','Download')}</div></div><div class="slides-layout"><nav class="slide-list" aria-label="Páginas da apresentação">${titles.map((title,index)=>B(`<span>0${index+1}</span><span>${title}</span>`,'slide','slide-thumb','',`data-index="${index}" aria-pressed="${slide===index}"`)).join('')}</nav><div><section class="slide-stage ${slide===1?'light':''}" aria-label="Página ${slide+1} de 4">${body}<div class="slide-brand"><strong>CLARA.</strong><span>${E(source().name)} · ${slide+1} / 4</span></div></section><div class="slide-controls">${B('Anterior','previous-slide','secondary','ArrowLeft',slide===0?'disabled':'')}<span>Use as setas do teclado · página ${slide+1} de 4</span>${B('Próxima','next-slide','secondary','ArrowRight',slide===3?'disabled':'')}</div><section class="slide-editor"><label class="field" for="summary">Sua leitura para abrir a apresentação<textarea id="summary" maxlength="1500" placeholder="O que você quer que a equipe entenda?">${E(state.summary)}</textarea></label><p class="tiny-note">Texto escrito por você. O download preserva esse resumo, as observações e os cálculos do recorte atual.</p></section></div></div>`;
}
function dialog(title:string,description:string,content:string,cls=''){const node=$<HTMLDialogElement>('#dialog');if(!node.open)dialogOpener=focusSelector(document.activeElement as HTMLElement);if(node.open)node.close();node.className=cls;node.setAttribute('aria-label',title||'Busca de ações e análises');node.innerHTML=`${title?`<div class="dialog-head"><h2>${E(title)}</h2>${B('','close','icon-button','X','aria-label="Fechar painel"')}</div>`:''}${description?`<p class="dialog-description">${E(description)}</p>`:''}${content}`;node.showModal();}
function close(){$<HTMLDialogElement>('#dialog').close();if(dialogOpener)(document.querySelector<HTMLElement>(dialogOpener)||$('#main')).focus({preventScroll:true});}
function newDialog(){dialog('Uma nova pergunta.','Escolha os dados e um ponto de partida. Você poderá ajustar tudo no explorador.',`${selectField('Fonte da análise','new-source',state.sources.map(s=>({value:s.id,label:s.name})),source().id)}<div class="template-options">${B(`<div><strong>Explorar os grupos</strong><small>Indicadores, filtros e detalhes lado a lado.</small></div>`,'template','','ChartBar','data-template="groups"')}${B(`<div><strong>Comparar dois períodos</strong><small>Atual, referência e variação conferíveis.</small></div>`,'template','','ChartLine','data-template="compare"')}${B(`<div><strong>Investigar uma exceção</strong><small>Comece por um grupo acima do orçamento.</small></div>`,'template','','CircleAlert','data-template="exception"')}${B(`<div><strong>Trazer meus dados</strong><small>Importe e confira um arquivo antes de analisar.</small></div>`,'import','','Upload')}</div>`);}
function openBoard(id:string){const board=state.boards.find(item=>item.id===id);if(!board)return;state.work={sourceId:board.sourceId,plan:clone(board.plan),notes:clone(board.notes),boardId:board.id};state.summary='';lastMessage='';persist();close();navigate('explore');}
function switchSource(id:string){const s=state.sources.find(item=>item.id===id);if(!s)return;state.work={sourceId:id,plan:blankPlan(s),notes:[]};lastMessage='';state.summary='';event('Fonte selecionada: '+s.name);render();}
function configuration(){const s=source(),p=plan();dialog('Seu jeito de analisar.','Os ajustes recalculam a prévia. Salve quando estiver pronta.',`<form id="config-form"><div class="dialog-grid"><label class="field wide" for="analysis-title">Título<input id="analysis-title" maxlength="100" required value="${E(p.title)}"></label>${selectField('Indicador principal','primary-metric',resolved().metrics.map(item=>({value:item.key,label:item.label})),p.primaryMetric)}${selectField('Separar por','config-group',s.columns.filter(item=>item.type!=='number').map(item=>({value:item.key,label:item.label})),p.groupBy)}${selectField('Orçamento','config-budget',[{value:'__none__',label:'Sem comparação'},...(s.budgetMetric?[{value:s.budgetMetric,label:fieldLabel(s,s.budgetMetric)}]:[])],p.secondaryMetric||'__none__')}</div><h3>Indicadores para acompanhar</h3>${resolved().metrics.map(item=>`<label class="choice"><input type="checkbox" name="selected-metric" value="${E(item.key)}" ${p.selectedMetrics?.includes(item.key)?'checked':''}>${E(item.label)}</label>`).join('')}<div id="config-error" class="error" role="alert" hidden></div><div class="dialog-actions">${B('Cancelar','close','secondary')}<button type="submit" class="primary">Aplicar à prévia ${I('Check')}</button></div></form><div class="dialog-section"><h3>Crie outra pergunta com os mesmos dados.</h3><p class="muted small">Indicadores calculados ampliam o olhar sem alterar sua fonte.</p>${B('Criar indicador calculado','formula','secondary','Calculator','style="margin-top:12px"')}</div>`,'drawer');}
function formulaDialog(){dialog('Um indicador, outra perspectiva.','A fórmula usa os campos da fonte e é calculada em cada registro, com o motor da CLARA.',`<form id="formula-form"><div class="dialog-grid"><label class="field wide" for="formula-name">Nome do indicador<input id="formula-name" value="Saldo por registro" maxlength="80" required></label><label class="field wide" for="formula-expression">Fórmula<input id="formula-expression" maxlength="500" value="${source().budgetMetric?'['+source().budgetMetric+'] - ['+source().primaryMetric+']':'['+source().primaryMetric+'] * 1.1'}" required></label>${selectField('Operação','formula-operation',[{value:'sum',label:'Somar resultados'},{value:'average',label:'Média por registro'}],'sum')}${selectField('Unidade','formula-unit',[{value:'BRL',label:'Reais (R$)'},{value:'number',label:'Número'}],metric().unit)}</div><div class="formula-fields">${source().columns.filter(item=>item.type==='number').map(item=>B(`${E(item.label)} [${E(item.key)}]`,'formula-field','','',`data-key="${E(item.key)}"`)).join('')}</div><p class="formula-help">Operadores: + − × ÷ e parênteses. Vazios e divisão por zero ficam fora do cálculo, com indicação.</p><div id="formula-preview" class="formula-preview"></div><div id="formula-error" class="error" role="alert" hidden></div><div class="dialog-actions">${B('Cancelar','close','secondary')}<button type="submit" class="primary">Adicionar indicador ${I('Plus')}</button></div></form>`,'drawer');previewFormula();}
function previewFormula(){try{const expression=$<HTMLInputElement>('#formula-expression').value;const compiled=compileExpression(expression,source().columns.filter(item=>item.type==='number').map(item=>item.key));const m:Metric={key:'calc_preview',label:'Prévia',expression,unit:$<HTMLSelectElement>('#formula-unit').value as Metric['unit'],operation:$<HTMLSelectElement>('#formula-operation').value as Metric['operation']};const result=calculate(m,rows());const omitted=rows().filter(row=>compiled.evaluate(row)==null).length;$('#formula-preview').innerHTML=`Resultado no recorte atual<strong>${fv(result,m)}</strong>${omitted} registros excluídos por resultado inválido.`;$('#formula-preview').hidden=false;$('#formula-error').hidden=true;}catch(error){$('#formula-preview').hidden=true;showError('formula-error',error);}}
function showError(id:string,error:unknown){const node=document.getElementById(id);if(node){node.textContent=error instanceof Error?error.message:'Confira os campos e tente novamente.';node.hidden=false;}else notify(error instanceof Error?error.message:'Não foi possível concluir.',true);}
function comparisonDialog(){if(!source().dateColumn){notify('Esta fonte não tem datas para comparar.',true);return;}const dates=filterValues(source(),source().dateColumn!).filter(v=>v.length===7);if(dates.length<2){notify('São necessários dois meses para comparar.',true);return;}dialog('O que mudou de um período para outro?','Os filtros de grupos e os critérios da fonte permanecem iguais nos dois cálculos.',`<form id="compare-form"><div class="dialog-grid">${selectField('Período atual','compare-current',dates.map(value=>({value,label:displayCell(source(),source().dateColumn!,value)})),plan().periodComparison?.current||dates.at(-1)!)}${selectField('Período de referência','compare-previous',dates.map(value=>({value,label:displayCell(source(),source().dateColumn!,value)})),plan().periodComparison?.previous||dates.at(-2)!)}</div><div id="compare-error" class="error" role="alert" hidden></div><div class="dialog-actions">${B('Cancelar','close','secondary')}<button type="submit" class="primary">Comparar períodos ${I('ChartLine')}</button></div></form>`);}
function multiDialog(){const key=plan().groupBy,values=valuesFor(source(),key);dialog('Selecione o que faz sentido.','Valores do mesmo campo são combinados com OU. Os demais filtros são preservados.',`<form id="multi-form"><h3>${E(fieldLabel(source(),key))}</h3>${values.slice(0,200).map(value=>`<label class="choice"><input type="checkbox" name="group-selection" value="${E(value)}" ${plan().filterSelections?.[key]?.includes(value)?'checked':''}>${E(value)}</label>`).join('')}${values.length>200?'<p class="tiny-note">200 primeiros valores. Use o gráfico e os registros para investigar outros grupos.</p>':''}<div class="dialog-actions">${B('Cancelar','close','secondary')}<button class="primary" type="submit">Aplicar seleção ${I('Filter')}</button></div></form>`,'drawer');}
function saveDialog(){dialog('Uma análise para voltar.','Salvar preserva fonte, recorte, indicadores e observações somente neste navegador.',`<form id="save-form"><label class="field" for="save-title">Nome da análise<input id="save-title" value="${E(plan().title)}" maxlength="100" required></label><div class="dialog-actions">${B('Cancelar','close','secondary')}<button type="submit" class="primary">${state.work.boardId?'Salvar nova versão':'Salvar análise'} ${I('Save')}</button></div></form>`);}
function historyDialog(){const board=state.boards.find(item=>item.id===state.work.boardId);if(!board){notify('Salve esta análise para começar seu histórico.');return;}dialog('Os caminhos desta análise.','Restaurar cria uma nova versão local. A fonte continua sendo a atual.',`<div class="actions">${B('Duplicar análise','duplicate','secondary','Copy',`data-id="${board.id}"`)}</div><div class="version-row"><div><p>Versão ${board.revisions.length+1}: ${E(board.plan.title)}</p><small>Atual · ${E(when(board.at))}</small></div><span class="tag">Atual</span></div>${board.revisions.map((version,index)=>`<div class="version-row"><div><p>Versão ${index+1}: ${E(version.plan.title)}</p><small>${E(when(version.at))}</small></div>${B('Restaurar','restore-version','secondary','Undo2',`data-id="${board.id}" data-index="${index}"`)}</div>`).reverse().join('')}`);}
function qualityDialog(id=source().id){const s=state.sources.find(item=>item.id===id)!;dialog('Antes do número, a fonte.',`${s.name} · ${s.rows.length} registros · revisão ${s.revision}`,`<span class="tag ${s.origin==='sap-demo'?'orange':'green'}">${s.origin==='sap-demo'?'Dados demonstrativos · SAP simulado':'Arquivo real · importação local'}</span><div class="source-quality table-scroll"><table class="data-table"><caption>Conferência de todos os registros da fonte</caption><thead><tr><th scope="col">Coluna</th><th scope="col">Tipo</th><th scope="col">Ausentes</th><th scope="col">Inválidos</th></tr></thead><tbody>${sourceQuality(s).map(item=>`<tr><th scope="row">${E(item.label)}</th><td>${E(s.columns.find(col=>col.key===item.key)!.type)}</td><td>${item.missing}</td><td>${item.invalid}</td></tr>`).join('')}</tbody></table></div><p class="formula-help">${s.rule?'Critério da fonte: '+E(fieldLabel(s,s.rule.column))+' = '+E(s.rule.value):'Sem critério adicional: todos os registros da fonte podem participar.'}</p><div class="dialog-actions">${B('Conferir registros','records','secondary','Table',`data-id="${s.id}"`)}${B('Explorar esta fonte','source-open','primary','ArrowUpRight',`data-id="${s.id}"`)}</div>`);}
function filteredRecords(){const s=state.sources.find(item=>item.id===recordSource)!;return (s.id===source().id?rows():s.rows).filter(row=>!recordQuery||Object.values(row).some(value=>String(value??'').toLocaleLowerCase('pt-BR').includes(recordQuery.toLocaleLowerCase('pt-BR'))));}
function recordMarkup(){const s=state.sources.find(item=>item.id===recordSource)!,data=filteredRecords(),pages=Math.max(1,Math.ceil(data.length/20));recordPage=Math.min(recordPage,pages-1);return `<div class="table-scroll"><table class="data-table"><caption>Registros da fonte · ${s.id===source().id?'após critérios e filtros atuais':'fonte completa'}</caption><thead><tr>${s.columns.map(col=>`<th scope="col">${E(col.label)}</th>`).join('')}</tr></thead><tbody>${data.slice(recordPage*20,recordPage*20+20).map(row=>`<tr>${s.columns.map(col=>`<td>${row[col.key]==null?'—':col.type==='date'?E(displayCell(s,col.key,String(row[col.key]))):E(row[col.key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="record-caption"><span>${data.length} registros encontrados · página ${recordPage+1} / ${pages}</span><div class="actions">${B('Anterior','records-previous','secondary','',recordPage===0?'disabled':'')}${B('Próxima','records-next','secondary','',recordPage>=pages-1?'disabled':'')}</div></div>`;}
function recordsDialog(id=source().id){recordSource=id;recordQuery='';recordPage=0;dialog('Os registros por trás do resultado.','Busque valores e confira as linhas consideradas. Seus dados não são enviados a serviços externos.',`<div class="record-search"><input id="record-search" class="search-input" type="search" aria-label="Buscar nos registros" placeholder="Buscar em qualquer coluna…"></div><div id="record-data">${recordMarkup()}</div>`);$('#dialog').style.width='min(940px,calc(100% - 32px))';}
function importDialog(){pendingImport=null;dialog('Traga seus dados para a conversa.','CSV, XLSX com uma aba ou JSON. Até 8 MB, 20 mil registros e 50 colunas.',`<label class="field" for="import-file">Escolher arquivo<input id="import-file" type="file" accept=".csv,.xlsx,.json"></label><p class="formula-help">A fonte só é adicionada após a conferência. Nenhum arquivo é enviado ao servidor.</p><div id="import-progress" class="muted small" role="status" style="margin-top:14px"></div><div id="import-error" class="error" role="alert" hidden></div><div id="import-preview"></div>`);}
function previewImport(sample:ImportSample){pendingImport=sample;const nums=sample.columns.filter(col=>col.type==='number'),groups=sample.columns.filter(col=>col.type!=='number'),dates=sample.columns.filter(col=>col.type==='date');$('#import-preview').innerHTML=`<div class="dialog-section"><h3>${sample.rows.length.toLocaleString('pt-BR')} registros encontrados.</h3><form id="import-form"><div class="dialog-grid"><label class="field wide" for="source-name">Nome da fonte<input id="source-name" maxlength="100" required value="${E(sample.name)}"></label>${selectField('Indicador','import-metric',sample.columns.map(col=>({value:col.key,label:col.label})),nums[0]?.key||sample.columns[0].key)}${selectField('Agrupamento','import-group',groups.map(col=>({value:col.key,label:col.label})),groups.find(col=>col.type==='text')?.key||groups[0].key)}${selectField('Operação','import-operation',[{value:'sum',label:'Somar'},{value:'average',label:'Média'},{value:'count',label:'Contar preenchidos'}],nums.length?'sum':'count')}${selectField('Unidade','import-unit',[{value:'number',label:'Número'},{value:'BRL',label:'Reais (R$)'}],'number')}${selectField('Datas','import-date',[{value:'__none__',label:'Sem data'},...dates.map(col=>({value:col.key,label:col.label}))],dates[0]?.key||'__none__')}${selectField('Orçamento','import-budget',[{value:'__none__',label:'Sem orçamento'},...nums.map(col=>({value:col.key,label:col.label}))],'__none__')}</div><div class="local-notice" id="import-summary"></div><div class="table-scroll"><table class="data-table"><caption>Primeiros 5 de ${sample.rows.length} registros</caption><thead><tr>${sample.columns.map(col=>`<th scope="col">${E(col.label)}</th>`).join('')}</tr></thead><tbody>${sample.rows.slice(0,5).map(row=>`<tr>${sample.columns.map(col=>`<td>${E(row[col.key]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="dialog-actions">${B('Cancelar','close','secondary')}<button class="primary" type="submit">Confirmar e explorar ${I('ArrowUpRight')}</button></div></form></div>`;updateImportSummary();}
function updateImportSummary(){if(!pendingImport)return;const label=(key:string)=>pendingImport!.columns.find(col=>col.key===key)?.label||key;const op=getValue('import-operation'),met=getValue('import-metric'),grp=getValue('import-group'),unit=$<HTMLSelectElement>('#import-unit');unit.disabled=op==='count';if(op==='count')unit.value='number';$('#import-summary').textContent=`${op==='sum'?'Somar':op==='average'?'Calcular média de':'Contar valores preenchidos de'} ${label(met)} por ${label(grp)}, considerando todos os registros. Unidade: ${unit.value==='BRL'?'reais':'número'}. ${getValue('import-date')!=='__none__'?'Datas: '+label(getValue('import-date'))+'. ':''}${getValue('import-budget')!=='__none__'?'Comparação com '+label(getValue('import-budget'))+'.':''}`;}
function calculationDialog(){const exceptions=analysisExceptions(source(),plan());dialog('O caminho deste número.','Fonte, recorte e operação. Nada fica escondido atrás do indicador.',`<div class="local-notice"><strong>${E(metric().label)}: ${fv(calculate(metric(),rows()))}</strong></div><ol style="padding-left:22px;line-height:1.8"><li><strong>Fonte:</strong> ${E(source().name)}, revisão ${source().revision}.</li><li><strong>Critério:</strong> ${source().rule?E(fieldLabel(source(),source().rule!.column))+' = '+E(source().rule!.value):'Todos os registros da fonte.'}</li><li><strong>Recorte:</strong> ${rows().length} registros considerados de ${source().rows.length}.</li><li><strong>Cálculo:</strong> ${E(calculationText(metric(),source()))}</li></ol>${exceptions.map(item=>`<p class="formula-help">${E(item.metric.label)}: ${item.omitted} registros não produzem um resultado válido e ficam fora do cálculo.</p>`).join('')}<div class="dialog-actions">${B('Ver registros','records','secondary','Table')}${B('Qualidade da fonte','quality','primary','Eye')}</div>`);}
function commandDialog(){dialog('','',`<div class="command-input">${I('Search')}<input id="command-search" aria-label="Buscar ação ou análise" placeholder="Uma análise, um dado, uma ação…" autocomplete="off">${B('','close','icon-button','X','aria-label="Fechar busca"')}</div><div id="command-results" class="command-results">${commandResults('')}</div><div class="command-footer"><span>Enter abre o primeiro resultado · setas navegam</span><span>Esc fecha</span></div>`,'command-dialog');$('#command-search').focus();}
function commandResults(query:string){const actions=[{title:'Criar uma análise',desc:'Começar por uma pergunta',action:'new',icon:'Plus'},{title:'Importar dados',desc:'CSV, Excel ou JSON',action:'import',icon:'Upload'},{title:'Criar indicador calculado',desc:'Fórmulas com prévia',action:'formula',icon:'Calculator'},{title:'Comparar períodos',desc:'Atual e referência',action:'compare',icon:'ChartLine'},{title:'Explorar meus dados',desc:'Filtros, gráficos e registros',action:'nav',icon:'ChartNoAxesCombined',extra:'data-screen="explore"'},...state.boards.map(board=>({title:board.plan.title,desc:'Análise salva neste navegador',action:'open-board',icon:'FolderOpen',extra:`data-id="${board.id}"`}))];return actions.filter(item=>(item.title+' '+item.desc).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))).map(item=>B(`<div>${E(item.title)}<small>${E(item.desc)}</small></div>`,item.action,'command-result',item.icon,item.extra||'')).join('')||'<p class="muted small" style="padding:20px">Nenhum resultado. Tente “fórmula”, “importar” ou o nome de uma análise.</p>';}
function exportHtml(presentationMode:boolean){const html=executiveReportHtml(source(),plan(),presentationMode);const extra=(state.summary?`<section><h1>Sua leitura</h1><p>${E(state.summary)}</p></section>`:'')+(state.work.notes.length?`<section><h1>Observações</h1>${state.work.notes.map(note=>`<p>${E(note.text)}</p>`).join('')}</section>`:'');download(html.replace('<main>','<main>'+extra),plan().title+(presentationMode?' - apresentação':' - relatório'),'html','text/html;charset=utf-8');event(presentationMode?'Apresentação exportada':'Relatório exportado');notify('Arquivo conferível baixado. Abra no navegador para imprimir ou salvar PDF.');}
function getValue(id:string){return $<HTMLInputElement|HTMLSelectElement>(`#${id}`).value;}

document.addEventListener('click',e=>{const button=(e.target as HTMLElement).closest<HTMLElement>('[data-action]');if(!button||button.hasAttribute('disabled'))return;const action=button.dataset.action!,id=button.dataset.id||'';try{
  if(action==='close'){close();return;}
  if(action==='nav'){close();navigate(button.dataset.screen as Screen);return;}
  if(action==='menu'){dialog('Seu espaço CLARA.','Navegue entre as etapas do seu trabalho.',`<nav>${navMarkup()}</nav>`,'menu-dialog');return;}
  if(action==='workspace'){dialog('Seu espaço de análise.','Este protótipo funciona localmente no navegador, com o motor de cálculos da CLARA.',`<div class="local-notice">${state.sources.length} fontes · ${state.boards.length} análises salvas. A aplicação principal mantém contas, equipes, permissões e auditoria no servidor.</div>${B('Exportar análises em JSON','export-state','primary','Download')}`);return;}
  if(action==='export-state'){download(JSON.stringify(state,null,2),'CLARA - espaço local','json','application/json');notify('Cópia do estudo local exportada.');return;}
  if(action==='command'){commandDialog();return;}
  if(action==='activity'){dialog('O que mudou no seu trabalho.','Até 30 ações recentes deste estudo, neste navegador.',state.events.length?state.events.map(item=>`<div class="activity-row">${I('CircleCheck')}<div>${E(item.text)}<small>${E(when(item.at))}</small></div></div>`).join(''):'<p class="muted">Você ainda não fez ajustes neste estudo. Experimente investigar um grupo.</p>');return;}
  if(action==='new'){newDialog();return;}
  if(action==='template'){switchSource(getValue('new-source'));const mode=button.dataset.template;close();navigate('explore');if(mode==='compare')comparisonDialog();if(mode==='exception'){const top=budgetExceptions(source(),plan()).find(item=>item.key===plan().groupBy);if(top)apply({...plan(),filters:{[top.key]:top.value}},'Investigação aberta: '+top.value);else notify('Esta fonte não tem grupo acima de orçamento definido. Explore os valores disponíveis.');}return;}
  if(action==='source-open'){close();switchSource(id);navigate('explore');return;}
  if(action==='open-board'){openBoard(id);return;}
  if(action==='favorite'){const board=state.boards.find(item=>item.id===id)!;board.favorite=!board.favorite;persist();render(true);notify(board.favorite?'Análise adicionada aos favoritos.':'Análise removida dos favoritos.');return;}
  if(action==='all-boards'||action==='favorite-boards'){favoriteOnly=action==='favorite-boards';render();return;}
  if(action==='drill'){close();const key=button.dataset.key!,value=button.dataset.value!,next=clone(plan());delete next.filterSelections?.[key];if(valuesFor(source(),key).includes(value)||filterValues(source(),key).includes(value)){next.filters[key]=value;apply(next,'Investigação: '+fieldLabel(source(),key)+' = '+value);if(screen!=='explore')navigate('explore');notify('Recorte aplicado. Use Limpar recorte para voltar.');}else notify('Este grupo reúne campos ausentes; confira as linhas em Ver registros.',true);return;}
  if(action==='clear-filter'){const next=clone(plan());delete next.filters[button.dataset.key!];delete next.filterSelections?.[button.dataset.key!];apply(next,'Filtro removido');return;}
  if(action==='reset'){apply({...plan(),filters:{},filterSelections:undefined},'Recorte restaurado');return;}
  if(action==='chart-bar'||action==='chart-line'){chartMode=action==='chart-bar'?'bar':'line';render(true);return;}
  if(action==='sort'){sortAscending=!sortAscending;render(true);return;}
  if(action==='configure'){configuration();return;}
  if(action==='formula'){formulaDialog();return;}
  if(action==='formula-field'){const input=$<HTMLInputElement>('#formula-expression');const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.value=input.value.slice(0,start)+`[${button.dataset.key}]`+input.value.slice(end);input.focus();input.setSelectionRange(start+button.dataset.key!.length+2,start+button.dataset.key!.length+2);previewFormula();return;}
  if(action==='compare'||action==='quick-compare'){comparisonDialog();return;}
  if(action==='remove-compare'){apply({...plan(),periodComparison:undefined},'Comparação de períodos removida');return;}
  if(action==='multi'){multiDialog();return;}
  if(action==='save'){saveDialog();return;}
  if(action==='history'){historyDialog();return;}
  if(action==='duplicate'){const board=state.boards.find(item=>item.id===id)!;const copy:Board={...clone(board),id:crypto.randomUUID(),plan:{...clone(board.plan),title:board.plan.title.slice(0,88)+' — cópia'},at:new Date().toISOString(),revisions:[]};state.boards.unshift(copy);event('Análise duplicada: '+copy.plan.title);openBoard(copy.id);notify('Cópia criada. A análise original foi preservada.');return;}
  if(action==='restore-version'){const board=state.boards.find(item=>item.id===id)!;const version=board.revisions[Number(button.dataset.index)];dialog('Restaurar esta leitura?','Será criada outra versão local, mantendo o histórico.',`<p>${E(version.plan.title)}</p><div class="dialog-actions">${B('Cancelar','close','secondary')}${B('Confirmar restauração','confirm-version','primary','Undo2',`data-id="${id}" data-index="${button.dataset.index}"`)}</div>`);return;}
  if(action==='confirm-version'){const board=state.boards.find(item=>item.id===id)!;const version=clone(board.revisions[Number(button.dataset.index)]);board.revisions.push({plan:clone(board.plan),at:board.at});board.plan=validatePlan(version.plan,state.sources.find(s=>s.id===board.sourceId)!);board.at=new Date().toISOString();event('Versão restaurada: '+board.plan.title);openBoard(id);notify('Uma nova versão preserva a restauração.');return;}
  if(action==='quality'){qualityDialog(id||undefined);return;}
  if(action==='records'){recordsDialog(id||undefined);return;}
  if(action==='records-next'||action==='records-previous'){recordPage+=action==='records-next'?1:-1;$('#record-data').innerHTML=recordMarkup();return;}
  if(action==='calculation'){calculationDialog();return;}
  if(action==='trend-values'){dialog('O tempo, em valores exatos.','Os mesmos períodos, grupos e critérios do gráfico.',valueTable(true));return;}
  if(action==='import'){importDialog();return;}
  if(action==='slide'){slide=Number(button.dataset.index);render(true);return;}
  if(action==='previous-slide'||action==='next-slide'){slide=Math.max(0,Math.min(3,slide+(action==='next-slide'?1:-1)));render(true);return;}
  if(action==='export-csv'){download(contextualCsv(source(),plan()),plan().title+' - contexto','csv','text/csv;charset=utf-8');event('CSV com contexto exportado');notify('CSV baixado com fonte, recorte e cálculos.');return;}
  if(action==='export-report'||action==='export-slides'){exportHtml(action==='export-slides');return;}
}catch(error){notify(error instanceof Error?error.message:'Não foi possível concluir.',true);}});

document.addEventListener('submit',e=>{const form=e.target as HTMLFormElement;if(!form.id)return;e.preventDefault();try{
  if(form.id==='prompt-form'){const prompt=getValue('prompt');state.work.prompt='';const next=demoPlan(prompt,source(),plan());lastMessage=next.message;if(next.status==='ready')apply(validatePlan(next,source()),'Pergunta aplicada com regras demonstrativas');else render();return;}
  if(form.id==='note-form'){const text=getValue('note').trim();if(!text)return;state.work.noteDraft='';state.work.notes.push({text,at:new Date().toISOString()});event('Observação adicionada ao recorte');render();notify('Observação preservada no trabalho atual.');return;}
  if(form.id==='config-form'){const next={...plan(),title:getValue('analysis-title').trim(),primaryMetric:getValue('primary-metric'),groupBy:getValue('config-group'),secondaryMetric:getValue('config-budget')==='__none__'?null:getValue('config-budget'),selectedMetrics:[...form.querySelectorAll<HTMLInputElement>('input[name="selected-metric"]:checked')].map(input=>input.value)};apply(next,'Configuração da análise atualizada');close();notify('Prévia recalculada. Salve para criar uma versão.');return;}
  if(form.id==='formula-form'){const item:Metric&{expression:string}={key:'calc_'+crypto.randomUUID().replaceAll('-',''),label:getValue('formula-name').trim(),expression:getValue('formula-expression'),operation:getValue('formula-operation') as Metric['operation'],unit:getValue('formula-unit') as Metric['unit']};const next={...plan(),calculatedMetrics:[...(plan().calculatedMetrics||[]),item],selectedMetrics:[...(plan().selectedMetrics||[]),item.key]};apply(next,'Indicador calculado criado: '+item.label);close();if(screen!=='explore')navigate('explore');notify('Indicador incluído com cálculo por registro.');return;}
  if(form.id==='compare-form'){const next={...plan(),periodComparison:{dateColumn:source().dateColumn!,current:getValue('compare-current'),previous:getValue('compare-previous')}};apply(next,'Dois períodos comparados');close();if(screen!=='explore')navigate('explore');return;}
  if(form.id==='multi-form'){const values=[...form.querySelectorAll<HTMLInputElement>('input[name="group-selection"]:checked')].map(input=>input.value),next=clone(plan());delete next.filters[next.groupBy];next.filterSelections={...next.filterSelections};if(values.length)next.filterSelections[next.groupBy]=values;else delete next.filterSelections[next.groupBy];apply(next,'Seleção de grupos atualizada');close();return;}
  if(form.id==='save-form'){const next=validatePlan({...plan(),title:getValue('save-title').trim()},source());const existing=state.boards.find(item=>item.id===state.work.boardId),at=new Date().toISOString();if(existing){existing.revisions.push({plan:clone(existing.plan),at:existing.at});existing.plan=clone(next);existing.notes=clone(state.work.notes);existing.at=at;}else{const board:Board={id:crypto.randomUUID(),sourceId:source().id,plan:clone(next),notes:clone(state.work.notes),at,favorite:false,revisions:[]};state.boards.unshift(board);state.work.boardId=board.id;}state.work.plan=next;event('Análise salva: '+next.title);close();render();notify('Análise e observações salvas neste navegador.');return;}
  if(form.id==='import-form'){if(!pendingImport)throw new Error('Escolha o arquivo novamente.');const sample=pendingImport,key=getValue('import-metric'),group=getValue('import-group'),date=getValue('import-date'),budget=getValue('import-budget'),operation=getValue('import-operation') as Metric['operation'],unit=getValue('import-unit') as Metric['unit'];const column=sample.columns.find(col=>col.key===key)!;if(operation!=='count'&&column.type!=='number')throw new Error('Para somar ou calcular média, escolha uma coluna numérica.');if(budget!=='__none__'&&(operation!=='sum'||budget===key))throw new Error('Orçamento exige soma e outra coluna numérica.');const s:Source={id:crypto.randomUUID(),owner:'prototype',name:getValue('source-name').trim(),origin:'file',domain:'Arquivo importado',columns:sample.columns,rows:sample.rows,metrics:[{key,label:column.label,unit:operation==='count'?'number':unit,operation},...(budget!=='__none__'?[{key:budget,label:sample.columns.find(col=>col.key===budget)!.label,unit,operation:'sum' as const}]:[])],primaryMetric:key,budgetMetric:budget==='__none__'?undefined:budget,groupBy:group,dateColumn:date==='__none__'?undefined:date,createdAt:new Date().toISOString(),revision:1};validatePlan(blankPlan(s),s);state.sources.push(s);pendingImport=null;close();switchSource(s.id);event('Arquivo importado: '+s.name+' · '+s.rows.length+' registros');navigate('explore');notify('Fonte adicionada. Todos os registros foram importados.');return;}
}catch(error){showError(form.id==='config-form'?'config-error':form.id==='compare-form'?'compare-error':form.id==='formula-form'?'formula-error':form.id==='import-form'?'import-error':'',error);}});

document.addEventListener('change',async e=>{const input=e.target as HTMLInputElement|HTMLSelectElement;try{
  if(input.id==='active-source'){switchSource(input.value);return;}
  if(input.id==='period-filter'){const next=clone(plan());delete next.filters[source().dateColumn!];delete next.filterSelections?.[source().dateColumn!];if(input.value!=='__all__')next.filters[source().dateColumn!]=input.value;apply(next,'Período da consulta alterado');return;}
  if(input.id==='group-by'){apply({...plan(),groupBy:input.value},'Agrupamento alterado');return;}
  if(input.id==='formula-operation'||input.id==='formula-unit'){previewFormula();return;}
  if(input.id.startsWith('import-')&&input.id!=='import-file'){updateImportSummary();return;}
  if(input.id==='import-file'){const file=(input as HTMLInputElement).files?.[0];if(!file)return;pendingImport=null;$('#import-preview').innerHTML='';$('#import-error').hidden=true;$('#import-progress').textContent='Lendo arquivo e conferindo colunas…';try{const sample=parseFile(new Uint8Array(await file.arrayBuffer()),file.name);previewImport(sample);$('#import-progress').textContent='Arquivo lido. Confira a operação antes de confirmar.';}catch(error){showError('import-error',error);$('#import-progress').textContent='';}return;}
}catch(error){notify(error instanceof Error?error.message:'Não foi possível alterar.',true);}});
document.addEventListener('input',e=>{const input=e.target as HTMLInputElement|HTMLTextAreaElement;
  if(input.id==='board-search'){boardSearch=input.value;const list=state.boards.filter(board=>(!favoriteOnly||board.favorite)&&board.plan.title.toLocaleLowerCase('pt-BR').includes(boardSearch.toLocaleLowerCase('pt-BR')));$('#board-results').innerHTML=list.map(boardCard).join('')||'<div class="empty"><h3>Nenhuma análise encontrada</h3><p>Tente outro nome.</p></div>';}
  if(input.id==='command-search')$('#command-results').innerHTML=commandResults(input.value);
  if(input.id==='record-search'){recordQuery=input.value;recordPage=0;$('#record-data').innerHTML=recordMarkup();}
  if(input.id==='formula-expression')previewFormula();
  if(input.id==='summary'){state.summary=input.value;persist();}
  if(input.id==='prompt'){state.work.prompt=input.value;persist();}
  if(input.id==='note'){state.work.noteDraft=input.value;persist();}
});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($<HTMLDialogElement>('#dialog').open)close();else commandDialog();return;}
  if($<HTMLDialogElement>('#dialog').open&&$('#dialog').classList.contains('command-dialog')){const results=[...document.querySelectorAll<HTMLButtonElement>('.command-result')];const index=results.indexOf(document.activeElement as HTMLButtonElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();results[(index+(e.key==='ArrowDown'?1:-1)+results.length)%results.length]?.focus();}if(e.key==='Enter'&&document.activeElement?.id==='command-search'){e.preventDefault();results[0]?.click();}return;}
  if(screen==='present'&&!$<HTMLDialogElement>('#dialog').open&&!['INPUT','TEXTAREA','SELECT'].includes((e.target as HTMLElement).tagName)){if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();slide=Math.max(0,Math.min(3,slide+(e.key==='ArrowRight'?1:-1)));render();}}
});
$<HTMLDialogElement>('#dialog').addEventListener('close',()=>{const node=$<HTMLDialogElement>('#dialog');if(node.open)return;node.style.width='';if(dialogOpener&&document.activeElement===document.body){(document.querySelector<HTMLElement>(dialogOpener)||$('#main')).focus({preventScroll:true});}});
window.addEventListener('popstate',()=>{const requested=location.hash.slice(1) as Screen;if(Object.keys(routeNames).includes(requested)){screen=requested;render();}});
window.CLARA_PROTOTYPE={navigate,state:()=>clone(state)};
const requested=location.hash.slice(1) as Screen;if(Object.keys(routeNames).includes(requested))screen=requested;render();persist();
